<?php
namespace App\Services;use App\Models\FraudAlert;use App\Models\Payment;use App\Models\PaymentRefund;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;
final class WompiRefundService{
 public function request(Payment $payment,int $cents,string $reason,int $adminId):PaymentRefund{if(!$payment->provider_transaction_id||$payment->provider!=='wompi'||$payment->status!=='completed')throw new \DomainException('Solo se reembolsan pagos Wompi aprobados.');if(!filled(config('payments.wompi.private_key')))throw new \RuntimeException('Falta la llave privada Wompi.');$refund=DB::transaction(function()use($payment,$cents,$reason,$adminId){$locked=Payment::lockForUpdate()->findOrFail($payment->id);$reserved=PaymentRefund::where('payment_id',$locked->id)->whereIn('status',['pending','approved','unknown'])->sum('amount_in_cents');if($cents<100||$reserved+$cents>(int)$locked->amount_in_cents)throw new \DomainException('El reembolso supera el saldo disponible.');return PaymentRefund::create(['payment_id'=>$locked->id,'requested_by'=>$adminId,'amount_in_cents'=>$cents,'reason'=>$reason,'reference'=>'REF-'.$locked->id.'-'.Str::upper(Str::random(16)),'status'=>'pending']);});try{$response=Http::acceptJson()->withToken(config('payments.wompi.private_key'))->timeout(20)->post(rtrim(config('payments.wompi.api_url'),'/').'/refunds',['transaction_id'=>$payment->provider_transaction_id,'amount_in_cents'=>$cents,'reason'=>$reason,'reference'=>$refund->reference]);if(!$response->successful()){$refund->update(['status'=>$response->status()>=500?'unknown':'error','provider_response'=>$response->json()?:['body'=>substr($response->body(),0,1000)],'processed_at'=>now()]);throw new \RuntimeException('Wompi no acepto el reembolso; revisa su estado antes de reintentar.');}$data=$response->json('data')??[];$status=match(strtoupper((string)($data['status']??''))){'APPROVED'=>'approved','DECLINED'=>'declined','CANCELLED'=>'cancelled','ERROR'=>'error',default=>'unknown'};$refund->update(['status'=>$status,'provider_refund_id'=>$data['v2_refund_id']??(isset($data['id'])?(string)$data['id']:null),'provider_response'=>$data,'processed_at'=>now()]);if($status==='approved')$this->adjustEarning($refund);return $refund;}catch(\Illuminate\Http\Client\ConnectionException $e){$refund->update(['status'=>'unknown','provider_response'=>['error'=>'network_timeout'],'processed_at'=>now()]);throw new \RuntimeException('Respuesta incierta de Wompi; concilia antes de reintentar.');}}
 private function adjustEarning(PaymentRefund $refund):void{$earning=$refund->payment->trip?->earning;if(!$earning)return;$ratio=$refund->amount_in_cents/max(1,(int)$refund->payment->amount_in_cents);if($earning->status==='paid'){FraudAlert::firstOrCreate(['fingerprint'=>hash('sha256','refund_after_payout:'.$refund->id)],['user_id'=>$earning->driver_id,'trip_id'=>$earning->trip_id,'rule'=>'refund_after_payout','severity'=>'critical','status'=>'open','summary'=>'Reembolso aprobado despues de pagar al conductor.','details'=>['refund_id'=>$refund->id,'amount_in_cents'=>$refund->amount_in_cents],'detected_at'=>now()]);return;}$gross=max(0,(float)$earning->gross_amount-round((float)$earning->gross_amount*$ratio,2));$fee=round($gross*((float)$earning->commission_rate/100),2);$earning->update(['gross_amount'=>$gross,'platform_fee'=>$fee,'net_amount'=>round($gross-$fee,2)]);}
}